import requests
from abc import ABC, abstractmethod
from urllib.parse import urljoin

class BaseCrawler(ABC):
    def __init__(self, config):
        self.config = config
        self.session = requests.Session()
        self.session.headers.update({'User-Agent': 'GazetteCrawler/1.0'})

    @abstractmethod
    def discover_documents(self):
        pass

    def fetch_url(self, url):
        try:
            response = self.session.get(url, timeout=10)
            response.raise_for_status()
            return response.text
        except requests.exceptions.RequestException as e:
            print(f"Error fetching {url}: {e}")
            return None

class GhanaGazetteCrawler(BaseCrawler):
    def discover_documents(self):
        base_url = self.config['sources'][0]['base_url']
        document_list_html = self.fetch_url(base_url)
        if not document_list_html:
            return []

        # Simple example: extract all links ending with .pdf
        from bs4 import BeautifulSoup
        soup = BeautifulSoup(document_list_html, 'html.parser')
        links = [a['href'] for a in soup.find_all('a', href=True) if a['href'].endswith('.pdf')]
        
        return [urljoin(base_url, link) for link in links]

# src/gazette_crawler/processors/pdf_processor.py
import PyPDF2

def process_pdf(file_path):
    with open(file_path, 'rb') as file:
        reader = PyPDF2.PdfReader(file)
        text = ''
        for page in reader.pages:
            text += page.extract_text()
        return text

# src/gazette_crawler/processors/html_processor.py
from bs4 import BeautifulSoup

def process_html(html_content):
    soup = BeautifulSoup(html_content, 'html.parser')
    # Remove script/style elements
    for script in soup(['script', 'style']):
        script.decompose()
    return soup.get_text()

# src/gazette_crawler/storage/database.py
from sqlalchemy import create_engine, Column, String, Text, DateTime, ForeignKey
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker
import hashlib

Base = declarative_base()

class Document(Base):
    __tablename__ = 'documents'
    id = Column(String, primary_key=True)
    content_hash = Column(String, unique=True)
    file_path = Column(String)
    source_id = Column(String)

class Metadata(Base):
    __tablename__ = 'metadata'
    document_id = Column(String, ForeignKey('documents.id'), primary_key=True)
    url = Column(String)
    date = Column(DateTime)
    publication_type = Column(String)
    raw_content = Column(Text)

def init_db(engine):
    Base.metadata.create_all(engine)

def save_to_db(engine, document_id, content_hash, file_path, source_id, url, date, publication_type, raw_content):
    Session = sessionmaker(bind=engine)
    session = Session()
    
    document = Document(
        id=document_id,
        content_hash=content_hash,
        file_path=file_path,
        source_id=source_id
    )
    metadata = Metadata(
        document_id=document_id,
        url=url,
        date=date,
        publication_type=publication_type,
        raw_content=raw_content[:4096]  # Limit text length
    )
    
    session.add(document)
    session.add(metadata)
    session.commit()
    session.close()

# src/gazette_crawler/storage/file_storage.py
import os
from datetime import datetime

def save_file(content, file_path):
    os.makedirs(os.path.dirname(file_path), exist_ok=True)
    with open(file_path, 'wb') as f:
        f.write(content)

def generate_file_path(source_name, url, content_hash):
    # Extract date from URL (simple example)
    date_str = url.split('/')[-2]  # Assuming URL format like .../2023/05/
    date_obj = datetime.strptime(date_str, '%Y/%m')
    
    return f"data/{source_name}/{date_obj.year}/{date_obj.month}/{content_hash}.pdf"

# src/gazette_crawler/indexer/elasticsearch_indexer.py
from elasticsearch import Elasticsearch
from datetime import datetime

def connect_elasticsearch():
    es = Elasticsearch(hosts=["http://localhost:9200"])
    if not es.ping():
        raise ValueError("Connection failed")
    return es

def index_document(es, document_id, content, metadata):
    doc = {
        'id': document_id,
        'content': content[:10000],  # Limit text length
        'url': metadata['url'],
        'date': metadata['date'].isoformat(),
        'publication_type': metadata['publication_type']
    }
    es.index(index="legal_documents", body=doc)

# src/gazette_crawler/main.py
import os
from gazette_crawler.config_loader import load_config
from gazette_crawler.crawler import GhanaGazetteCrawler
from gazette_crawler.storage.database import init_db, save_to_db
from gazette_crawler.storage.file_storage import save_file, generate_file_path
from gazette_crawler.indexer.elasticsearch_indexer import connect_elasticsearch, index_document
from gazette_crawler.processors.pdf_processor import process_pdf

def main():
    config = load_config('config.yaml')
    
    # Initialize database
    engine = create_engine('sqlite:///legal_docs.db')  # For demo, using SQLite
    init_db(engine)
    
    # Initialize Elasticsearch
    es = connect_elasticsearch()
    
    # Initialize crawler
    crawler = GhanaGazetteCrawler(config)
    document_urls = crawler.discover_documents()
    
    for url in document_urls:
        # Download document
        response = requests.get(url)
        if response.status_code != 200:
            continue
            
        content = response.content
        
        # Generate content hash
        content_hash = hashlib.sha256(content).hexdigest()
        
        # Check for duplicates
        # (In real implementation, check database first)
        
        # Generate file path
        source_name = config['sources'][0]['name']
        file_path = generate_file_path(source_name, url, content_hash)
        
        # Save to file
        save_file(content, file_path)
        
        # Process content
        if url.endswith('.pdf'):
            text_content = process_pdf(file_path)
        else:
            # For HTML, use html_processor
            pass
        
        # Create document metadata
        document_id = f"doc_{content_hash}"
        date_str = url.split('/')[-2]  # Simple date extraction
        date = datetime.strptime(date_str, '%Y/%m')
        
        # Save to database
        save_to_db(
            engine,
            document_id=document_id,
            content_hash=content_hash,
            file_path=file_path,
            source_id=config['sources'][0]['name'],
            url=url,
            date=date,
            publication_type=config['sources'][0]['document_type'],
            raw_content=text_content
        )
        
        # Index in Elasticsearch
        index_document(
            es,
            document_id,
            text_content,
            {
                'url': url,
                'date': date,
                'publication_type': config['sources'][0]['document_type']
            }
        )

if __name__ == "__main__":
    main()

# tests/test_crawler.py
import unittest
from gazette_crawler.crawler import GhanaGazetteCrawler
from unittest.mock import patch, MagicMock

class TestGhanaGazetteCrawler(unittest.TestCase):
    @patch('gazette_crawler.crawler.requests.Session.get')
    def test_discover_documents(self, mock_get):
        mock_response = MagicMock()
        mock_response.status_code = 200
        mock_response.text.return_value = """
            <html>
                <body>
                    <a href="notice1.pdf">Notice 1</a>
                    <a href="notice2.pdf">Notice 2</a>
                </body>
            </html>
        """
        mock_get.return_value = mock_response
        
        config = {
            'sources': [{
                'name': 'Ghana Gazette',
                'base_url': 'https://www.ghanagazetteonline.gov.gh/',
                'document_type': 'statutory_instrument'
            }]
        }
        
        crawler = GhanaGazetteCrawler(config)
        urls = crawler.discover_documents()
        
        self.assertEqual(len(urls), 2)
        self.assertEqual(urls[0], 'https://www.ghanagazetteonline.gov.gh/notice1.pdf')
        self.assertEqual(urls[1], 'https://www.ghanagazetteonline.gov.gh/notice2.pdf')

